from bs4.element import Tag
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from app.filter.main import Filter


class AdsFilter:
    """Filters out ad content from search results."""

    def __init__(self, filter_instance: 'Filter'):
        self.filter = filter_instance

    def remove_ads(self) -> None:
        """Removes ads found in the list of search result divs

        Returns:
            None (The soup object is modified directly)
        """
        if not self.filter.main_divs:
            return

        for div in [_ for _ in self.filter.main_divs.find_all('div', recursive=True)]:
            div_ads = [_ for _ in div.find_all('span', recursive=True)
                       if self.filter.has_ad_content(_.text)]
            _ = div.decompose() if len(div_ads) else None
